//! JPEG 2000 **Part-1** EBCOT context look-up tables and MQ context labels. These drive the
//! bit-plane coding passes in [`crate::coding::ojph_block_decoder_part1`]. The 19 MQ contexts
//! (T.800 Table D.7) are partitioned as: 0..=8 zero-coding (ZC) per subband orientation, 9..=13
//! sign-coding (SC), 14..=16 magnitude-refinement (MR), 17 run-length (RL), 18 uniform (UNI).
//!
//! [`SIG_LUT`] maps `[orientation][8-bit neighbour-significance pattern] -> ZC context (0..=8)`,
//! where the 8-bit index packs the neighbours as `TL=0 TR=1 BL=2 BR=3 T=4 B=5 L=6 R=7`. [`SIGN_LUT`]
//! maps `[8-bit sign/significance pattern]` to the SC context (`[0]`, 9..=13) and the
//! sign-prediction XOR bit (`[1]`, 0/1). Tables verbatim from OpenHTJ2K `EBCOTtables.hpp` (the
//! standard ISO context tables), mechanically converted so no value is hand-transcribed.

/// MQ context label of the run-length (RL) coding primitive.
pub const CTX_RL: u8 = 17;
/// MQ context label of the uniform (UNI) coding primitive.
pub const CTX_UNI: u8 = 18;
/// Magnitude-refinement context base: 14 (first refinement, no significant neighbour), 15 (first
/// refinement with a significant neighbour), 16 (subsequent refinements).
pub const CTX_MR: [u8; 3] = [14, 15, 16];

