#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn tables_have_valid_context_ranges() {
        for o in 0..4 {
            assert!(
                SIG_LUT[o].iter().all(|&c| c <= 8),
                "ZC context out of 0..=8"
            );
        }
        assert!(
            SIGN_LUT[0].iter().all(|&c| c == 0 || (9..=13).contains(&c)),
            "SC context"
        );
        assert!(SIGN_LUT[1].iter().all(|&b| b <= 1), "sign XOR bit");
        // Spot checks against the reference source.
        assert_eq!(&SIG_LUT[3][0..8], &[0, 3, 3, 6, 3, 6, 6, 8]);
        assert_eq!(&SIGN_LUT[0][16..20], &[0, 10, 0, 9]);
        assert_eq!(CTX_MR, [14, 15, 16]);
    }
}
